contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(uint _initMinSum, uint _newMinSum) public {
        c.SetMinSum(_initMinSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint m0 = c.MinSum(); if (__ESBMC_reverted()) return;
        bool ok;
        c.SetMinSum(_newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        assert(!ok || c.MinSum() == m0);
    }

    receive() external payable {}
    fallback() external payable {}
}

