pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 _initMinSum, uint256 _newMinSum) internal {
        try c.SetMinSum(_initMinSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 m0;
        try c.MinSum() returns (uint256 __r) { m0 = __r; } catch { return; }
        bool ok;
        try c.SetMinSum(_newMinSum) { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.MinSum() == m0);
    }

    function testFuzz_test(uint256 _initMinSum, uint256 _newMinSum) public {
        _test(_initMinSum, _newMinSum);
    }

    receive() external payable {}

    fallback() external payable {}
}
